<script src="assets/js/comun.js?v=20261002-1"></script>
<script>
const isAdmin=<?= Auth::isAdmin() ? 'true' : 'false' ?>;let catalogs={regiones:[],choferes:[],rutas:[],maquinas:[]};let draftMachines=new Set();let operationalDashboard=null;let operationalJourneys=[];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const refreshIcons=()=>window.cargarLucide?.().then(x=>x.createIcons()).catch(()=>{});
function animateMetric(el,target){if(!el)return;target=Number(target)||0;if(matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=target.toLocaleString('es-MX');return}const start=performance.now(),duration=520;const tick=now=>{const p=Math.min(1,(now-start)/duration),ease=1-Math.pow(1-p,3);el.textContent=Math.round(target*ease).toLocaleString('es-MX');if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)}
async function api(action,opts={}){const r=await fetch(`api/abastecimiento.php?accion=${action}`,opts),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'No se pudo completar la operacion');return j.data}
function openModal(name){document.getElementById(`modal-${name}`).classList.add('open')}function closeModals(){document.querySelectorAll('.overlay').forEach(x=>x.classList.remove('open'))}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModals);document.querySelectorAll('.overlay').forEach(x=>x.addEventListener('click',e=>{if(e.target===x)closeModals()}));
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const n=b.dataset.open,form=document.getElementById(`form-${n}`);form?.reset();form?.querySelector('[type=hidden]')&&(form.querySelector('[type=hidden]').value='');if(n==='ruta'){draftMachines=new Set();document.getElementById('machine-search').value='';renderMachinePicker()}openModal(n);refreshIcons()});
function activateTab(name){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));document.querySelectorAll('[data-go-tab]').forEach(x=>x.classList.toggle('active',x.dataset.goTab===name));['prioridades','regiones','rutas','choferes','jornadas'].forEach(n=>document.getElementById(`view-${n}`).hidden=n!==name);if(name==='jornadas')loadJourneys()}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>activateTab(b.dataset.tab));document.querySelectorAll('[data-go-tab]').forEach(b=>b.onclick=()=>{activateTab(b.dataset.goTab);document.querySelector('.panel').scrollIntoView({behavior:'smooth',block:'start'})});
function fillSelect(sel,items,label){const current=sel.value,first=sel.options[0]?.outerHTML||'';sel.innerHTML=first+items.map(x=>`<option value="${x.id_region??x.id_ruta??x.id_chofer}">${esc(label(x))}</option>`).join('');sel.value=current}
async function loadCatalogs(){catalogs=await api('catalogos');document.querySelectorAll('.region-options').forEach(s=>fillSelect(s,catalogs.regiones,x=>x.nombre));document.querySelectorAll('.driver-options').forEach(s=>fillSelect(s,catalogs.choferes,x=>x.nombre));document.querySelectorAll('.route-options').forEach(s=>{s.innerHTML=catalogs.rutas.filter(x=>x.estatus==='activa').map(x=>`<option value="${x.id_ruta}">${esc(x.clave)} · ${esc(x.nombre)}</option>`).join('')});fillSelect(document.getElementById('f-region'),catalogs.regiones,x=>x.nombre);fillSelect(document.getElementById('f-ruta'),catalogs.rutas,x=>`${x.clave} · ${x.nombre}`);fillSelect(document.getElementById('f-chofer'),catalogs.choferes,x=>x.nombre);document.getElementById('flow-regiones').textContent=catalogs.regiones.length;document.getElementById('flow-rutas').textContent=catalogs.rutas.filter(x=>x.estatus==='activa').length;document.getElementById('flow-choferes').textContent=catalogs.choferes.length;renderRegions();renderRoutes();renderDrivers();renderDispatch();refreshIcons()}
function priority(p){return `<span class="priority ${esc(p)}">${esc(p)}</span>`}function stockColor(p){return p<=15?'#c44f5b':p<=35?'#c56d2d':p<=60?'#b18a2e':'#3aaa4a'}
async function loadDashboard(){const p=new URLSearchParams();[['q','f-q'],['region','f-region'],['ruta','f-ruta'],['chofer','f-chofer'],['prioridad','f-prioridad'],['asignacion','f-asignacion']].forEach(([k,id])=>{const v=document.getElementById(id).value;if(v)p.set(k,v)});const d=await api('dashboard&'+p.toString());operationalDashboard=d;Object.entries({total:'total',criticas:'criticas',altas:'altas','sin-ruta':'sin_ruta',piezas:'piezas_faltantes'}).forEach(([id,k])=>{const raw=Number(d.resumen[k]||0);document.getElementById('k-'+id).textContent=raw.toLocaleString('es-MX');animateMetric(document.getElementById('d-'+id),raw)});renderDispatch();const el=document.getElementById('machine-table');if(!d.maquinas.length){el.innerHTML='<div class="empty">No hay maquinas con estos filtros.</div>';return}el.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Prioridad</th><th>Maquina</th><th>Region / ruta asignada</th><th>Responsable</th><th>Nivel de llenado</th><th>Carga requerida</th></tr></thead><tbody>${d.maquinas.map((m,i)=>`<tr class="attention-row" style="--row-color:${stockColor(m.porcentaje_llenado)}"><td>${priority(m.prioridad)}</td><td><div class="machine-cell"><span class="rank">${String(i+1).padStart(2,'0')}</span><div><strong class="mono">${esc(m.numero_serie)}</strong><div class="muted">${esc(m.nombre_ubicacion||m.nombre_maquina||'Sin ubicacion')}</div></div></div></td><td><strong>${esc(m.region_nombre||m.region_geografica)}</strong><div class="route-label ${m.ruta_nombre?'':'unassigned'}"><i data-lucide="${m.ruta_nombre?'route':'route-off'}"></i>${m.ruta_nombre?esc(m.ruta_clave+' · '+m.ruta_nombre):'Pendiente de asignar ruta'}</div></td><td>${m.chofer_nombre?`<strong>${esc(m.chofer_nombre)}</strong>`:'<span class="unassigned">Por asignar</span>'}</td><td><div class="stock"><div class="stock-line"><strong>${Number(m.porcentaje_llenado).toFixed(1)}%</strong><span>${m.piezas_actuales}/${m.capacidad_total}</span></div><div class="bar"><i style="--w:${Math.min(100,m.porcentaje_llenado)}%;--bar:${stockColor(m.porcentaje_llenado)}"></i></div></div></td><td><strong>${Number(m.piezas_faltantes).toLocaleString('es-MX')} piezas</strong><div class="muted">${m.carriles_vacios} carriles vacios</div></td></tr>`).join('')}</tbody></table></div>`;refreshIcons()}
function renderRoutes(){const el=document.getElementById('route-cards');el.innerHTML=catalogs.rutas.length?catalogs.rutas.map(r=>`<article class="card route-card"><div class="card-top"><span class="card-symbol"><i data-lucide="route"></i></span><span class="status ${r.estatus==='activa'?'available':'off'}">${esc(r.estatus)}</span></div><div class="card-code">${esc(r.clave)}</div><h3>${esc(r.nombre)}</h3><div class="card-info"><div class="info-line"><i data-lucide="map-pin"></i>${esc(r.region_nombre)}</div><div class="info-line"><i data-lucide="contact"></i>${esc(r.chofer_nombre||'Chofer pendiente')}</div><div class="info-line"><i data-lucide="calendar-days"></i>${esc(r.dias_operacion||'Dias por definir')} ${r.hora_salida?'· '+esc(r.hora_salida):''}</div></div><div class="card-metrics"><div class="card-metric"><b>${Number(r.total_maquinas||0)}</b><span>Maquinas</span></div><div class="card-metric"><b>${Number(r.capacidad_piezas||0).toLocaleString('es-MX')}</b><span>Capacidad pzas.</span></div></div>${isAdmin?`<div class="row-actions"><button class="btn" onclick="editRoute(${r.id_ruta})"><i data-lucide="pencil"></i>Editar asignacion</button><button class="btn primary" onclick="newJourney(${r.id_ruta})"><i data-lucide="send"></i>Despachar</button></div>`:''}</article>`).join(''):'<div class="empty">Aun no hay rutas. Empieza creando una ruta dentro de una region.</div>'}
function renderRegions(){const el=document.getElementById('region-cards');el.innerHTML=catalogs.regiones.length?catalogs.regiones.map(r=>{const routes=catalogs.rutas.filter(x=>Number(x.id_region)===Number(r.id_region)),machines=routes.reduce((n,x)=>n+Number(x.total_maquinas||0),0);return `<article class="card"><div class="card-top"><span class="card-symbol"><i data-lucide="map"></i></span><span class="status available">Cobertura activa</span></div><div class="card-code">${esc(r.clave)}</div><h3>${esc(r.nombre)}</h3><div class="card-info"><div class="info-line"><i data-lucide="user-round"></i>${esc(r.responsable||'Responsable por asignar')}</div><div class="info-line"><i data-lucide="phone"></i>${esc(r.telefono||'Telefono no registrado')}</div></div><div class="card-metrics"><div class="card-metric"><b>${routes.length}</b><span>Rutas</span></div><div class="card-metric"><b>${machines}</b><span>Maquinas</span></div></div>${isAdmin?`<div class="row-actions"><button class="btn" onclick="editRegion(${r.id_region})"><i data-lucide="settings-2"></i>Configurar region</button></div>`:''}</article>`}).join(''):'<div class="empty">Aun no hay regiones operativas. Crea la primera para comenzar la cobertura.</div>'}
function renderDispatch(){
    const regionEl=document.getElementById('dispatch-regions'),routeEl=document.getElementById('dispatch-routes'),driverEl=document.getElementById('dispatch-drivers');
    if(!regionEl||!routeEl||!driverEl)return;
    regionEl.innerHTML=catalogs.regiones.length?catalogs.regiones.map(r=>{const routes=catalogs.rutas.filter(x=>Number(x.id_region)===Number(r.id_region)),machines=routes.reduce((n,x)=>n+Number(x.total_maquinas||0),0);return `<button class="region-row" type="button" onclick="openRegionPriority(${r.id_region})"><span class="region-marker">${esc(String(r.clave||'RG').slice(0,2))}</span><span><b>${esc(r.nombre)}</b><small>${routes.length} rutas activas</small></span><span class="region-total">${machines}</span></button>`}).join(''):'<div class="rail-loading">Sin regiones configuradas</div>';
    const activeRoutes=catalogs.rutas.filter(r=>r.estatus==='activa');
    routeEl.innerHTML=activeRoutes.length?activeRoutes.map(r=>{const trip=operationalJourneys.find(j=>Number(j.id_ruta)===Number(r.id_ruta)),state=!r.id_chofer?'Sin chofer':trip?.estatus==='en_ruta'?'En ruta':trip?.estatus==='programada'?'Programada':'Lista',color=!r.id_chofer?'#c7892b':trip?.estatus==='en_ruta'?'#4567b7':'#3aaa4a',driver=catalogs.choferes.find(d=>Number(d.id_chofer)===Number(r.id_chofer));return `<div class="dispatch-route" style="--route-color:${color}"><div class="route-identity"><span class="route-code-box">${esc(String(r.clave).slice(0,5))}</span><span><b>${esc(r.nombre)}</b><small>${esc(r.region_nombre)} · ${esc(r.dias_operacion||'Frecuencia pendiente')}</small></span></div><div class="coverage-count"><b>${Number(r.total_maquinas||0)}</b><small>maquinas</small></div><div class="unit-assignment ${driver?'':'unset'}"><span class="unit-avatar">${esc(initials(driver?.nombre||'?'))}</span><span><b>${esc(driver?.nombre||'Asignar chofer')}</b><small>${esc(driver?.placas||driver?.vehiculo||'Sin unidad')}</small></span></div><span class="route-state" style="--route-color:${color}">${state}</span>${isAdmin?`<button class="route-more" title="Editar ruta" onclick="editRoute(${r.id_ruta})"><i data-lucide="sliders-horizontal"></i></button>`:'<span></span>'}</div>`}).join(''):'<div class="deck-empty">No hay rutas activas. Configura la primera ruta de reparto.</div>';
    driverEl.innerHTML=catalogs.choferes.length?catalogs.choferes.slice(0,8).map(d=>`<div class="crew-person"><span class="avatar">${esc(initials(d.nombre))}</span><span><b>${esc(d.nombre)}</b><small>${esc(d.placas||d.vehiculo||d.region_nombre||'Sin unidad')}</small></span><i class="crew-state ${driverStatus(d.estatus)}" title="${esc(d.estatus)}"></i></div>`).join(''):'<div class="rail-loading">Sin choferes registrados</div>';
    if(operationalDashboard)renderInsights(operationalDashboard);
    refreshIcons();
}
function openRegionPriority(id){document.getElementById('f-region').value=String(id);activateTab('prioridades');loadDashboard();document.querySelector('.panel').scrollIntoView({behavior:'smooth',block:'start'})}
function renderInsights(data){
    const machines=data?.maquinas||[],total=machines.length,counts={critica:0,alta:0,media:0,normal:0};
    machines.forEach(m=>{if(Object.prototype.hasOwnProperty.call(counts,m.prioridad))counts[m.prioridad]++});
    const colors={critica:'#e11d48',alta:'#f59e0b',media:'#818cf8',normal:'#22c55e'},labels={critica:'Critica',alta:'Alta',media:'Media',normal:'Normal'};
    let cursor=0;const segments=Object.keys(counts).map(k=>{const start=cursor,end=total?cursor+(counts[k]/total*100):cursor;cursor=end;return `${colors[k]} ${start.toFixed(2)}% ${end.toFixed(2)}%`});
    document.getElementById('priority-donut').style.background=total?`conic-gradient(${segments.join(',')})`:'#e5e7eb';document.getElementById('donut-total').textContent=total.toLocaleString('es-MX');document.getElementById('priority-legend').innerHTML=Object.keys(counts).map(k=>`<div class="legend-row"><i style="background:${colors[k]}"></i><span>${labels[k]}</span><b>${counts[k]}</b></div>`).join('');
    const regions={};machines.forEach(m=>{const name=m.region_nombre||m.region_geografica||'Sin region';regions[name]??={total:0,risk:0};regions[name].total++;if(m.prioridad==='critica'||m.prioridad==='alta')regions[name].risk++});const rows=Object.entries(regions).map(([name,v])=>({name,...v,pct:v.total?Math.round(v.risk/v.total*100):0})).sort((a,b)=>b.pct-a.pct||b.risk-a.risk).slice(0,5);document.getElementById('region-bars').innerHTML=rows.length?rows.map((r,i)=>`<div class="region-bar-row"><span title="${esc(r.name)}">${esc(r.name)}</span><div class="region-bar-track"><i style="--bar-width:${r.pct}%;animation-delay:${i*70}ms"></i></div><b>${r.pct}%</b></div>`).join(''):'<div class="chart-placeholder">Sin datos regionales para mostrar.</div>';
    const unassigned=Number(data?.resumen?.sin_ruta||0),assigned=Math.max(0,total-unassigned),coverage=total?Math.round(assigned/total*100):0;document.getElementById('coverage-percent').textContent=`${coverage}%`;document.getElementById('coverage-assigned').textContent=assigned.toLocaleString('es-MX');document.getElementById('coverage-unassigned').textContent=unassigned.toLocaleString('es-MX');document.getElementById('coverage-bar').style.setProperty('--coverage',`${coverage}%`);
}
function initials(name){return String(name||'').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'CH'}function driverStatus(s){return s==='disponible'?'available':s==='en_ruta'?'busy':'off'}
function renderDrivers(){const el=document.getElementById('driver-cards');el.innerHTML=catalogs.choferes.length?catalogs.choferes.map(d=>`<article class="card"><div class="card-top"><div class="driver-head"><span class="avatar">${esc(initials(d.nombre))}</span><div><h3>${esc(d.nombre)}</h3><span class="card-code">${esc(d.numero_empleado||'Sin numero de empleado')}</span></div></div><span class="status ${driverStatus(d.estatus)}">${esc(d.estatus)}</span></div><div class="card-info"><div class="info-line"><i data-lucide="map-pin"></i>${esc(d.region_nombre||'Sin region fija')}</div><div class="info-line"><i data-lucide="truck"></i>${esc(d.vehiculo||'Vehiculo sin registrar')} ${d.placas?'· '+esc(d.placas):''}</div><div class="info-line"><i data-lucide="badge-check"></i>Licencia ${esc(d.licencia||'sin registrar')}</div><div class="info-line"><i data-lucide="calendar-clock"></i>${d.licencia_vigencia?'Vigente hasta '+esc(d.licencia_vigencia):'Vigencia no capturada'}</div></div>${isAdmin?`<div class="row-actions"><button class="btn" onclick="editDriver(${d.id_chofer})"><i data-lucide="pencil"></i>Editar expediente</button></div>`:''}</article>`).join(''):'<div class="empty">Aun no hay choferes registrados. Agrega personal y su unidad de reparto.</div>'}
function updateMachineCount(){const n=draftMachines.size;document.getElementById('machine-selected-count').textContent=`${n} ${n===1?'seleccionada':'seleccionadas'}`}
function renderMachinePicker(routeId=0){const q=(document.getElementById('machine-search').value||'').toLowerCase(),el=document.getElementById('machine-picker');el.innerHTML=catalogs.maquinas.filter(m=>(!m.id_ruta||Number(m.id_ruta)===Number(routeId))&&`${m.numero_serie} ${m.nombre_ubicacion} ${m.region_geografica}`.toLowerCase().includes(q)).map(m=>`<label class="machine-option"><input type="checkbox" name="maquinas" value="${m.id_maquina}" ${draftMachines.has(Number(m.id_maquina))?'checked':''}><b class="mono">${esc(m.numero_serie)}</b> ${esc(m.nombre_ubicacion||'')}<span>${esc(m.region_geografica)}</span></label>`).join('')||'<div class="empty">No hay maquinas disponibles.</div>';el.querySelectorAll('[name=maquinas]').forEach(x=>x.onchange=()=>{const id=Number(x.value);x.checked?draftMachines.add(id):draftMachines.delete(id);updateMachineCount()});updateMachineCount()}
document.getElementById('machine-search').oninput=()=>renderMachinePicker(Number(document.querySelector('#form-ruta [name=id_ruta]').value||0));
function setForm(form,data){Object.entries(data).forEach(([k,v])=>{const e=form.elements[k];if(e)e.value=v??''})}
function editDriver(id){const d=catalogs.choferes.find(x=>Number(x.id_chofer)===id);setForm(document.getElementById('form-chofer'),d);openModal('chofer')}
function editRegion(id){const r=catalogs.regiones.find(x=>Number(x.id_region)===id);setForm(document.getElementById('form-region'),r);openModal('region')}
function editRoute(id){const r=catalogs.rutas.find(x=>Number(x.id_ruta)===id);setForm(document.getElementById('form-ruta'),r);draftMachines=new Set(catalogs.maquinas.filter(x=>Number(x.id_ruta)===id).map(x=>Number(x.id_maquina)));document.getElementById('machine-search').value='';renderMachinePicker(id);openModal('ruta');refreshIcons()}
function newJourney(id){const f=document.getElementById('form-jornada');f.reset();f.elements.id_ruta.value=id;f.elements.fecha_operacion.value=new Date().toISOString().slice(0,10);openModal('jornada')}
async function submitForm(e,action,extra=()=>({})){e.preventDefault();const f=e.currentTarget,msg=f.querySelector('.form-msg'),data=Object.fromEntries(new FormData(f));Object.assign(data,extra(f));msg.textContent='Guardando…';try{await api(action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});closeModals();await loadCatalogs();await loadDashboard();msg.textContent=''}catch(err){msg.textContent=err.message}}
document.getElementById('form-region').onsubmit=e=>submitForm(e,'guardar_region');document.getElementById('form-chofer').onsubmit=e=>submitForm(e,'guardar_chofer');document.getElementById('form-ruta').onsubmit=e=>submitForm(e,'guardar_ruta',()=>({maquinas:[...draftMachines]}));document.getElementById('form-jornada').onsubmit=e=>submitForm(e,'generar_jornada');
async function loadJourneys(){const estado=document.getElementById('f-jornada').value,d=await api('jornadas&estado='+encodeURIComponent(estado)),el=document.getElementById('journey-table');operationalJourneys=d;document.getElementById('flow-jornadas').textContent=d.length;renderDispatch();if(!d.length){el.innerHTML='<div class="empty">No hay jornadas con este estado.</div>';return}el.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Ruta</th><th>Region</th><th>Chofer</th><th>Avance</th><th>Criticas</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${d.map(j=>`<tr><td class="mono">${esc(j.fecha_operacion)}</td><td><strong>${esc(j.ruta_clave)} · ${esc(j.ruta_nombre)}</strong></td><td>${esc(j.region_nombre)}</td><td>${esc(j.chofer_nombre||'Por asignar')}</td><td><strong>${Number(j.paradas_atendidas||0)}/${Number(j.total_paradas||0)}</strong><div class="muted">paradas atendidas</div></td><td>${Number(j.paradas_criticas||0)}</td><td><span class="status ${j.estatus==='en_ruta'?'busy':j.estatus==='completada'?'available':''}">${esc(j.estatus)}</span></td><td>${journeyActions(j)}</td></tr>`).join('')}</tbody></table></div>`;refreshIcons()}
function journeyActions(j){let a=`<button class="btn" onclick="showStops(${j.id_jornada})"><i data-lucide="list-checks"></i>Paradas</button>`;if(isAdmin&&j.estatus==='programada')a+=`<button class="btn primary" onclick="setJourney(${j.id_jornada},'en_ruta')"><i data-lucide="play"></i>Iniciar</button>`;if(isAdmin&&j.estatus==='en_ruta')a+=`<button class="btn primary" onclick="setJourney(${j.id_jornada},'completada')"><i data-lucide="circle-check"></i>Completar</button>`;return `<div class="row-actions">${a}</div>`}
async function setJourney(id,status){try{await api('estatus_jornada',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id_jornada:id,estatus:status})});loadJourneys()}catch(e){mlAlert(e.message)}}
async function showStops(id){openModal('paradas');const el=document.getElementById('stop-table');el.innerHTML='<div class="empty">Cargando paradas…</div>';try{const d=await api('detalle_jornada&id='+id);el.innerHTML=d.length?`<div class="table-wrap"><table><thead><tr><th>Orden</th><th>Prioridad</th><th>Maquina</th><th>Llenado al programar</th><th>Sugerido / entregado</th><th>Estado</th><th>Registro</th></tr></thead><tbody>${d.map(p=>`<tr><td><strong>${p.orden_visita}</strong></td><td>${priority(p.prioridad_snapshot)}</td><td><strong class="mono">${esc(p.numero_serie)}</strong><div class="muted">${esc(p.nombre_ubicacion||'')}</div></td><td>${Number(p.porcentaje_llenado_snapshot||0).toFixed(1)}%</td><td>${Number(p.piezas_sugeridas||0)} / ${Number(p.piezas_entregadas||0)}</td><td><span class="status">${esc(p.estatus)}</span>${p.incidencia?`<div class="muted">${esc(p.incidencia)}</div>`:''}</td><td>${isAdmin?`<div class="row-actions"><button class="btn" onclick="setStop(${p.id_parada},'en_sitio',${id})">En sitio</button><button class="btn primary" onclick="deliverStop(${p.id_parada},${id},${Number(p.piezas_sugeridas||0)})">Atender</button><button class="btn danger" onclick="incidentStop(${p.id_parada},${id})">Incidencia</button></div>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Esta jornada no tiene paradas.</div>'}catch(e){el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function setStop(id,status,jornada,extra={}){try{await api('actualizar_parada',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id_parada:id,estatus:status,...extra})});showStops(jornada);loadJourneys()}catch(e){mlAlert(e.message)}}
function deliverStop(id,jornada,sugeridas){const piezas=prompt('Piezas entregadas:',String(sugeridas));if(piezas===null)return;setStop(id,'atendida',jornada,{piezas_entregadas:Math.max(0,Number(piezas)||0)})}
function incidentStop(id,jornada){const incidencia=prompt('Describe la incidencia:','');if(!incidencia)return;setStop(id,'incidencia',jornada,{incidencia})}
let debounce;['f-q','f-region','f-ruta','f-chofer','f-prioridad','f-asignacion'].forEach(id=>document.getElementById(id).addEventListener(id==='f-q'?'input':'change',()=>{clearTimeout(debounce);debounce=setTimeout(loadDashboard,180)}));document.getElementById('f-jornada').onchange=loadJourneys;
loadCatalogs().then(()=>Promise.all([loadDashboard(),loadJourneys()])).then(refreshIcons).catch(e=>{document.getElementById('machine-table').innerHTML=`<div class="empty">${esc(e.message)}</div>`});
</script>
</body>
</html>
